        arc = (80, 200) if k == 1 else (-20, 100)      # with stones on the side of the water
        stone_ring(c[0], c[2], TOWER_R, MOAT_Y, G - 0.5, arc=(arc[0] * add.pi / 180, arc[1] * add.pi / 180))
