def dormer_valley(dz):
    """Where the dormer's roof runs into the chapel's west slope, ``dz``
    from its ridge line: the x of the valley."""
    return CH_C[0] - (CH_TOP + CH_RH - (DM_RO - abs(dz))) / CH_S


