LEG = [[0.0, 0.0], [0.05, 0.0], [0.052, 0.05], [0.038, 0.1], [0.042, 0.22], [0.06, 0.34], [0.042, 0.46], [0.036, 0.56],
       [0.05, 0.6], [0.05, 0.71], [0.0, 0.71]]         # (a turned profile, TH - 0.07 high)
