add.cylinder([TOOLS[0], TOOLS[1], TOOLS[2]], [TOOLS[0], TOOLS[1] + 0.85, TOOLS[2]], 0.02, 6, P["iron"])
add.torus([TOOLS[0], TOOLS[1] + 0.8, TOOLS[2]], 0.09, 0.012, 12, 4, P["iron"])
