    add.cuboid([CA_X0 + 0.15 + 0.3 * i, (CA_Y + FLOOR2 - 0.2 * i) / 2, CH_C[1]], [0.3, FLOOR2 - 0.2 * i - CA_Y, 2 * DM_I - 0.1],
               shade_of("wood", i + 1))
